from pathlib import Path
import re,ast
p=Path('planning/spec.md'); rows=[]; failures=[]
for line in p.read_text().splitlines():
 if not re.match(r'\| R-\d+',line):continue
 cells=[s.strip() for s in line.split('|')[1:-1]]
 if len(cells)!=4:failures.append(('columns',cells));continue
 rid,req,source,check=cells;rows.append(rid)
 paths=re.findall(r'`([^`]+\.(?:md|json))`',source)
 texts=[Path(path).read_text() for path in paths]
 quotes=re.findall('“(.*?)”',source)
 if not paths or not quotes:failures.append((rid,'missing source/quote'))
 for q in quotes:
  if not any(q in t for t in texts):failures.append((rid,'quote not verbatim',q))
 if not check:failures.append((rid,'empty check'))
 for name in re.findall(r'test_\w+',check):
  if name not in Path('tests/test_intake.py').read_text()+Path('tests/test_starter.py').read_text():failures.append((rid,'unknown test',name))
assert rows==[f'R-{n:02}' for n in range(1,len(rows)+1)],'IDs not sequential/unique'
print(f'{len(rows)} unique sequential IDs; {len(failures)} source/check failures')
for item in failures:print(item)
assert not failures
PY
